 // left vertical fill (border)
 root.spawn_bundle(left_vertical_fill_border())
    .with_children(|parent| {
       ...
    });

// right vertical fill
root.spawn_bundle(right_vertical_fill())
    .with_children(|parent| {
        ...
    });
